// ── Parse Telegram Command ───────────────────────────────
const telegramData = $input.item.json;

// Extract message text
const message   = telegramData.message || {};
const text      = (message.text || '').trim();
const chatId    = message.chat?.id || telegramData.chat_id;
const messageId = message.message_id;
const fromUser  = message.from?.username || message.from?.first_name || 'unknown';

// Parse commands:
// APPROVE <draft_id>
// EDIT <draft_id>: <feedback>
// REJECT <draft_id>: <reason>

const APPROVE_PATTERN = /^APPROVE\s+([\w\-]+)\s*$/i;
const EDIT_PATTERN    = /^EDIT\s+([\w\-]+)\s*:\s*([\s\S]+)$/i;
const REJECT_PATTERN  = /^REJECT\s+([\w\-]+)\s*:\s*([\s\S]+)$/i;

let command  = 'UNKNOWN';
let draftId  = '';
let feedback = '';
let reason   = '';

const approveMatch = text.match(APPROVE_PATTERN);
const editMatch    = text.match(EDIT_PATTERN);
const rejectMatch  = text.match(REJECT_PATTERN);

if (approveMatch) {
  command = 'APPROVE';
  draftId = approveMatch[1].trim();
} else if (editMatch) {
  command  = 'EDIT';
  draftId  = editMatch[1].trim();
  feedback = editMatch[2].trim();
} else if (rejectMatch) {
  command = 'REJECT';
  draftId = rejectMatch[1].trim();
  reason  = rejectMatch[2].trim();
}

return {
  command:    command,
  draft_id:   draftId,
  feedback:   feedback,
  reason:     reason,
  raw_text:   text,
  chat_id:    String(chatId),
  message_id: messageId,
  from_user:  fromUser,
  is_valid:   command !== 'UNKNOWN' && draftId !== ''
};

