// ── Parse Revised Draft from OpenAI ─────────────────────
const openAiOut    = $input.item.json;
const originalData = $('DB – Get Draft (EDIT)').first().json;
const cmdData      = $('Parse Telegram Command').first().json;

const rawContent = openAiOut.message?.content ||
                   openAiOut.choices?.[0]?.message?.content ||
                   '{}';

let revised;
try {
  revised = JSON.parse(rawContent);
} catch(e) {
  revised = {
    revised_subject: originalData.ai_suggested_subject,
    revised_body:    originalData.ai_suggested_reply + '\n\n[Revisado según feedback]',
    changes_made:    'No se pudo parsear la respuesta revisada'
  };
}

return {
  draft_id:           originalData.draft_id,
  message_id:         originalData.message_id,
  thread_id:          originalData.thread_id,
  from_email:         originalData.from_email,
  customer_name:      originalData.customer_name,
  company_name:       originalData.company_name,
  original_subject:   originalData.original_subject,
  original_ai_reply:  originalData.ai_suggested_reply,
  human_feedback:     cmdData.feedback,
  revised_subject:    revised.revised_subject || originalData.ai_suggested_subject,
  revised_body:       revised.revised_body    || originalData.ai_suggested_reply,
  changes_made:       revised.changes_made    || '',
  from_user:          cmdData.from_user,
  chat_id:            cmdData.chat_id
};

